# Generated by manage.py generate_test_cases.
from bs4 import BeautifulSoup

from bloomerp.tests.base import (
    BloomerpWidgetTestCase,
    WidgetOperation,
    WidgetScenario,
)
from bloomerp.widgets.booking_email_account_widget import BookingEmailAccountWidget


class TestBookingEmailAccountWidget(BloomerpWidgetTestCase):
    widget_class = BookingEmailAccountWidget

    def get_test_scenarios(self) -> list[WidgetScenario[BookingEmailAccountWidget]]:
        """Retain a saved account selection when it is outside the current choices."""
        return [
            WidgetScenario(
                name="An unavailable saved sender is shown with a neutral label",
                constructor_kwargs={"choices": [("", "---------"), ("allowed", "team@example.com")]},
                operations=[
                    WidgetOperation(
                        name="Render the saved sender",
                        execute=self.render_saved_sender,
                        result_validators=self.has_neutral_selected_option,
                    ),
                ],
            ),
        ]

    def render_saved_sender(self, widget: BookingEmailAccountWidget) -> str:
        """Render an existing sender outside the permitted choices."""
        return widget.render("email_account", "saved-account")

    def has_neutral_selected_option(self, rendered: str) -> bool:
        """Keep the saved choice selected while still showing allowed accounts."""
        markup = BeautifulSoup(rendered, "html.parser")
        selected = markup.select_one("option[selected]")
        return (
            selected is not None
            and selected["value"] == "saved-account"
            and selected.get_text(strip=True) == "Unavailable email account"
            and markup.select_one('option[value="allowed"]') is not None
        )
